/* ===== Material Design 3 — 100 native facets (data-spectrum="material3"). Token-driven, self-contained. ===== */
.material3-root{--material3-radius:12px;--material3-font:Roboto, -apple-system, "Segoe UI", system-ui, "Helvetica Neue", Arial, sans-serif;font-family:var(--material3-font,inherit)}
@keyframes material3BtnPulse{0%,100%{box-shadow:0 0 0 0 rgba(var(--_rgb),.5)}50%{box-shadow:0 0 0 6px rgba(var(--_rgb),0)}}
.material3-btn{display:inline-flex;align-items:center;gap:8px;padding:9px 18px;border-radius:var(--material3-radius,999px);background:var(--_c);color:#fff;font-weight:700;border:0;animation:material3BtnPulse 2.4s ease-in-out infinite}
@keyframes material3TgKnob{0%,100%{left:2px}50%{left:20px}}
.material3-toggle{position:relative;width:44px;height:24px;border-radius:999px;background:rgba(var(--_rgb),.28);border:1px solid rgba(var(--_rgb),.5)}
.material3-toggle::after{content:"";position:absolute;top:2px;left:2px;width:18px;height:18px;border-radius:50%;background:var(--_c);box-shadow:0 0 8px rgba(var(--_rgb),.7);animation:material3TgKnob 2.6s ease-in-out infinite}
@keyframes material3ChipShine{0%{background-position:-160% 0}60%,100%{background-position:260% 0}}
.material3-chip{position:relative;overflow:hidden;display:inline-flex;align-items:center;padding:4px 12px;border-radius:999px;background:rgba(var(--_rgb),.16);border:1px solid rgba(var(--_rgb),.4);color:var(--_c);font-size:12px;font-weight:700}
.material3-chip::after{content:"";position:absolute;inset:0;background:linear-gradient(110deg,transparent 40%,rgba(var(--_rgb),.4) 50%,transparent 60%);background-size:250% 100%;animation:material3ChipShine 3s linear infinite;pointer-events:none}
@keyframes material3MenuSel{0%,100%{background:rgba(var(--_rgb),.12)}50%{background:rgba(var(--_rgb),.26)}}
.material3-menu{min-width:150px;padding:6px;border-radius:var(--material3-radius,12px);background:var(--panel2);border:1px solid var(--line)}
.material3-menu .material3-mi{padding:7px 10px;border-radius:8px;color:var(--ink);font-size:12px}
.material3-menu .material3-sel{color:var(--_c);animation:material3MenuSel 2.8s ease-in-out infinite}
@keyframes material3NotifIn{0%,100%{transform:translateX(-6px);opacity:.75}50%{transform:translateX(0);opacity:1}}
.material3-toast{display:flex;align-items:center;gap:10px;padding:10px 14px;border-radius:10px;background:var(--panel2);border:1px solid var(--line);border-left:3px solid var(--_c);color:var(--ink);font-size:12px;animation:material3NotifIn 3s ease-in-out infinite}
.material3-toast::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--_c);box-shadow:0 0 8px rgba(var(--_rgb),.8)}
@keyframes material3CalloutEdge{0%{transform:translateX(-120%)}100%{transform:translateX(120%)}}
.material3-callout{position:relative;overflow:hidden;padding:10px 14px;border-radius:10px;background:rgba(var(--_rgb),.1);border:1px solid rgba(var(--_rgb),.35);color:var(--ink);font-size:12px}
.material3-callout::after{content:"";position:absolute;top:0;left:0;height:2px;width:60%;background:linear-gradient(90deg,transparent,var(--_c),transparent);animation:material3CalloutEdge 2.6s linear infinite;pointer-events:none}
@keyframes material3BarGrow{0%{transform:scaleY(.25)}50%{transform:scaleY(1)}100%{transform:scaleY(.25)}}
.material3-chart{display:flex;align-items:flex-end;gap:5px;height:44px;padding:6px 8px;border-radius:10px;background:var(--panel2);border:1px solid var(--line)}
.material3-chart i{flex:1;background:var(--_c);border-radius:3px 3px 0 0;transform-origin:bottom;animation:material3BarGrow 2.4s ease-in-out infinite}
.material3-chart i:nth-child(2){animation-delay:.2s}.material3-chart i:nth-child(3){animation-delay:.4s}.material3-chart i:nth-child(4){animation-delay:.6s}
@keyframes material3InputCaret{0%,49%{opacity:1}50%,100%{opacity:0}}
.material3-field{display:inline-flex;align-items:center;gap:2px;min-width:150px;padding:8px 11px;border-radius:10px;background:var(--panel);border:1px solid var(--_c);box-shadow:0 0 0 3px rgba(var(--_rgb),.18);color:var(--ink);font-size:12px}
.material3-field .material3-caret{width:1.5px;height:14px;background:var(--_c);animation:material3InputCaret 1.1s step-end infinite}
@keyframes material3Prog{0%{width:8%}80%,100%{width:96%}}
.material3-prog{width:150px;height:8px;border-radius:999px;background:rgba(var(--_rgb),.18);overflow:hidden}
.material3-prog i{display:block;height:100%;border-radius:inherit;background:var(--_c);box-shadow:0 0 8px rgba(var(--_rgb),.6);animation:material3Prog 3s ease-in-out infinite}
@keyframes material3AvRing{to{transform:rotate(1turn)}}
.material3-avatar{position:relative;width:46px;height:46px;border-radius:50%;display:grid;place-items:center;background:var(--panel2);color:var(--ink);font-weight:800}
.material3-avatar::before{content:"";position:absolute;inset:-3px;border-radius:50%;background:conic-gradient(from 0deg,var(--_c),transparent 55%,var(--_c));-webkit-mask:radial-gradient(farthest-side,transparent calc(100% - 3px),#000 calc(100% - 3px));mask:radial-gradient(farthest-side,transparent calc(100% - 3px),#000 calc(100% - 3px));animation:material3AvRing 3.4s linear infinite}
@keyframes material3BadgePop{0%,100%{transform:scale(1)}30%{transform:scale(1.25)}}
.material3-badge{display:inline-grid;place-items:center;min-width:22px;height:22px;padding:0 6px;border-radius:999px;background:var(--_c);color:#fff;font-size:11px;font-weight:800;animation:material3BadgePop 2s ease-in-out infinite}
@keyframes material3TabSlide{0%,100%{left:2px}50%{left:calc(50% + 1px)}}
.material3-tabs{position:relative;display:inline-flex;padding:3px;border-radius:999px;background:var(--panel2);border:1px solid var(--line)}
.material3-tabs span{position:relative;z-index:1;padding:5px 14px;font-size:12px;color:var(--ink)}
.material3-tabs::before{content:"";position:absolute;top:3px;bottom:3px;width:calc(50% - 3px);left:2px;border-radius:999px;background:rgba(var(--_rgb),.9);animation:material3TabSlide 3.2s ease-in-out infinite}
@keyframes material3TipFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-4px)}}
.material3-tip{display:inline-block;padding:6px 10px;border-radius:8px;background:var(--panel2);border:1px solid var(--_c);color:var(--ink);font-size:11px;box-shadow:0 4px 14px rgba(var(--_rgb),.3);animation:material3TipFloat 2.6s ease-in-out infinite}
@keyframes material3Spin{to{transform:rotate(1turn)}}
.material3-spinner{width:26px;height:26px;border-radius:50%;border:3px solid rgba(var(--_rgb),.22);border-top-color:var(--_c);animation:material3Spin 1s linear infinite}
@keyframes material3CardGlow{0%,100%{box-shadow:0 0 0 1px var(--line)}50%{box-shadow:0 0 16px rgba(var(--_rgb),.4)}}
.material3-card{width:150px;padding:12px;border-radius:var(--material3-radius,12px);background:var(--card);color:var(--ink);animation:material3CardGlow 3.4s ease-in-out infinite}
.material3-card b{color:var(--_c);font-size:12px}.material3-card p{margin:4px 0 0;font-size:11px;color:var(--muted)}
@keyframes material3CheckIn{0%,20%{clip-path:inset(0 100% 0 0)}60%,100%{clip-path:inset(0 0 0 0)}}
.material3-check{position:relative;width:22px;height:22px;border-radius:6px;background:var(--_c);display:grid;place-items:center}
.material3-check::after{content:"✓";color:#fff;font-size:14px;font-weight:900;animation:material3CheckIn 2.4s ease-in-out infinite}
@keyframes material3SliderThumb{0%,100%{left:2px}50%{left:calc(100% - 16px)}}
.material3-slider{position:relative;width:150px;height:6px;border-radius:999px;background:rgba(var(--_rgb),.2)}
.material3-slider::before{content:"";position:absolute;top:-5px;left:2px;width:16px;height:16px;border-radius:50%;background:var(--_c);box-shadow:0 0 8px rgba(var(--_rgb),.6);animation:material3SliderThumb 3s ease-in-out infinite}
@media(prefers-reduced-motion:reduce){.material3-root [class*="material3-"],.material3-root [class*="material3-"]::before,.material3-root [class*="material3-"]::after,.material3-root [class],.material3-root [class]::before,.material3-root [class]::after{animation:none!important}}

